INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(44811, 'Psalms 132:11', 'Psalms', 132, 11, 'څښتن خوړلی سخت قسم دی له داود سره داسې قسم چې هغه به یې نه ماتوي: «چې زه به یو کس ستا د زامنو څخه د ستا په تخت کښېنوم', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms132_verse_11.mp3', '', 1761754199, 1761754199),
(44812, 'Psalms 132:12', 'Psalms', 132, 12, 'که زما لوظ ته وفادار اوسي د ستا زامن او هغو حکمونو ته چې زه یې ورکوم نو د دوی زامن به تر ابده پورې ناست وي ستا په تخت باندې»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms132_verse_12.mp3', '', 1761754199, 1761754199),
(44813, 'Psalms 132:13', 'Psalms', 132, 13, 'ځکه څښتن دی خوښ کړی صهیون او هغه غوښتل چې ورنه جوړ کړي خپل کور', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms132_verse_13.mp3', '', 1761754199, 1761754199),
(44814, 'Psalms 132:14', 'Psalms', 132, 14, 'هغه وویل: «دا زما کور دی تر ابده پورې زه به اوسېږم دلته ځکه خوښ کړی دی ما', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms132_verse_14.mp3', '', 1761754199, 1761754199),
(44815, 'Psalms 132:15', 'Psalms', 132, 15, 'زه به یې پوره کړم حاجتونه ټول او غریبان به یې په خوړو ماړه کړم', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms132_verse_15.mp3', '', 1761754199, 1761754199),
(44816, 'Psalms 132:16', 'Psalms', 132, 16, 'کاهنان به یې سمبال کړم د خلاصون په لباس او وفادار خلک به یې چیغې وهي د خوشحالۍ', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms132_verse_16.mp3', '', 1761754199, 1761754199),
(44817, 'Psalms 132:17', 'Psalms', 132, 17, 'د داود د اولادې نه به یو تن قوي پاچا کړم دلته زما غوره شوی پاچا به وي څراغ زما د قوم دپاره', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms132_verse_17.mp3', '', 1761754199, 1761754199),
(44818, 'Psalms 132:18', 'Psalms', 132, 18, 'زه به رسوا کړم دښمنان د هغه خو زه به کامیابه او ښایسته کړم پاچاهي د هغه»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms132_verse_18.mp3', '', 1761754199, 1761754199),
(44819, 'Psalms 105:1', 'Psalms', 105, 1, 'کوئ شکر د څښتن او د هغه په نوم دعا کوئ! نورو قومونو ته دا ووایئ څه چې هغه کړي دي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms105_verse_1.mp3', '', 1761754199, 1761754199),
(44820, 'Psalms 105:2', 'Psalms', 105, 2, 'هغه ته حمد ووایئ ووایئ هغه ته د ثنا او صفت سندره هغه چې کړي عجیبه کارونه کړئ یې بیان خلکو ته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms105_verse_2.mp3', '', 1761754199, 1761754199),
(44821, 'Psalms 105:3', 'Psalms', 105, 3, 'په پاک نوم د هغه وکړئ افتخار وي دې خوشحاله څوک چې کاندي عبادت د هغه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms105_verse_3.mp3', '', 1761754199, 1761754199),
(44822, 'Psalms 105:4', 'Psalms', 105, 4, 'وغواړئ کومک له څښتنه وکړئ عبادت یې تل', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms105_verse_4.mp3', '', 1761754199, 1761754199),
(44823, 'Psalms 105:7', 'Psalms', 105, 7, 'دی څښتن زمونږه خدای راولي چې عدالت د ځمکې سر باندې هرځای', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms105_verse_7.mp3', '', 1761754199, 1761754199),
(44824, 'Psalms 105:8', 'Psalms', 105, 8, 'هغه ولاړ به تر ابده وي خپل لوظ باندې وي وعدې به د ده تر زرو نسلونو پورې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms105_verse_8.mp3', '', 1761754199, 1761754199),
(44825, 'Psalms 105:9', 'Psalms', 105, 9, 'هغه لوظ چې هغه وکړ د ابراهیم سره هغه قسم چې هغه وکړ د اسحاق سره', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms105_verse_9.mp3', '', 1761754199, 1761754199),
(44826, 'Psalms 105:10', 'Psalms', 105, 10, 'هغه یې ورکړلو یعقوب ته د یو حکم په شان او اسراییلو ته د ابدي لوظ په توګه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms105_verse_10.mp3', '', 1761754199, 1761754199),
(44827, 'Psalms 105:11', 'Psalms', 105, 11, 'هغه وویل: «تاسو ته در به کړم وطن د کنعان وي به هغه د ستاسو خپل ملکیت»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms105_verse_11.mp3', '', 1761754199, 1761754199),
(44828, 'Psalms 105:12', 'Psalms', 105, 12, 'کله چې شمېر د خدای د خلکو کم ؤ وو پردي د کنعان خاوره کې دوی', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms105_verse_12.mp3', '', 1761754199, 1761754199),
(44829, 'Psalms 105:13', 'Psalms', 105, 13, 'دوی سرګردانه ګرځېدل به یو او بل وطن کې تلل یو او بلې پاچاهۍ ته هغوی', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms105_verse_13.mp3', '', 1761754199, 1761754199),
(44830, 'Psalms 105:14', 'Psalms', 105, 14, 'خو خدای پرېنښودل هېڅوک چې په دوی ظلم وکړي د دوی دپاره یې شاهان ورټل', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms105_verse_14.mp3', '', 1761754199, 1761754199),
(44831, 'Psalms 105:15', 'Psalms', 105, 15, 'هغوی ته یې وویل: «زما غوره شویو بنده‌ګانو ته به لاس نه وروړئ ضرر به نه رسوئ زما پیغمبرانو ته»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms105_verse_15.mp3', '', 1761754199, 1761754199),
(44832, 'Psalms 105:16', 'Psalms', 105, 16, 'څښتن راوستله قحطي د دوی په خاوره او د خوړو وسیلې یې د دوی نه واخیستلې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms105_verse_16.mp3', '', 1761754199, 1761754199),
(44833, 'Psalms 105:17', 'Psalms', 105, 17, 'له دوی نه مخکې یې یو کس ولېږه یعنې یوسف چې شولو خرڅ لکه غلام په توګه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms105_verse_17.mp3', '', 1761754199, 1761754199),
(44834, 'Psalms 105:18', 'Psalms', 105, 18, 'وې تړلې پښې په زنځیرو ورته اوسپنې کړۍ یې ورته واچوله غاړه کې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms105_verse_18.mp3', '', 1761754199, 1761754199),
(44835, 'Psalms 105:19', 'Psalms', 105, 19, 'څو چې پېشګویي یې شوله رښتیا او عملونه یې ثابت کړل د څښتن کلام', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms105_verse_19.mp3', '', 1761754199, 1761754199),
(44836, 'Psalms 105:20', 'Psalms', 105, 20, 'پاچا د مصر کړ ازاد هغه یعنې د قومونو پاچا خوشې کړ', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms105_verse_20.mp3', '', 1761754199, 1761754199),
(44837, 'Psalms 105:21', 'Psalms', 105, 21, 'هغه یې مشر کړ د خپل حکومت خپل ټول ملکیت باندې حاکم کړلو', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms105_verse_21.mp3', '', 1761754199, 1761754199),
(44838, 'Psalms 105:22', 'Psalms', 105, 22, 'چې د پاچا په مامورینو باندې واک ولري او د پاچا سلاکارانو ته روزنه ورکړي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms105_verse_22.mp3', '', 1761754199, 1761754199),
(44839, 'Psalms 105:23', 'Psalms', 105, 23, 'نو بیا یعقوب لاړلو مصر ته شو استوګن هغه د حام وطن کې لکه پردي په شان', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms105_verse_23.mp3', '', 1761754199, 1761754199),
(44840, 'Psalms 105:24', 'Psalms', 105, 24, 'خپلو خلکو ته څښتن ډېر اولادونه ورکړل او دوی قوي یې کړل په خپلو دښمنانو باندې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms105_verse_24.mp3', '', 1761754199, 1761754199),
(44841, 'Psalms 105:25', 'Psalms', 105, 25, 'مصریان یې جوړ کړل دې ته چې د ده له قومه وکړي هغوی کرکه او چلند وکړي په ټګۍ د څښتن خلکو سره', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms105_verse_25.mp3', '', 1761754199, 1761754199),
(44842, 'Psalms 105:26', 'Psalms', 105, 26, 'بیا هغه ولېږه موسی خپل خادم او هم هارون چې غوره کړی یې ؤ', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms105_verse_26.mp3', '', 1761754199, 1761754199),
(44843, 'Psalms 105:27', 'Psalms', 105, 27, 'هغوی د خدای نښې ښکاره کړلې مصریانو ته او معجزې د هغه یې وښودې د حام په ځمکه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms105_verse_27.mp3', '', 1761754199, 1761754199),
(44844, 'Psalms 105:28', 'Psalms', 105, 28, 'په هغې وطن تیاره کړه خدای نازله موسی او هارون ونه کړه د خدای نافرماني', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms105_verse_28.mp3', '', 1761754199, 1761754199),
(44845, 'Psalms 105:29', 'Psalms', 105, 29, 'د سیند اوبه یې ورته بدلې کړې په وینو باندې او ټول کبان یې ورته مړه کړل', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms105_verse_29.mp3', '', 1761754199, 1761754199),
(44846, 'Psalms 105:30', 'Psalms', 105, 30, 'ډک شو وطن یې چونګښانو باندې په چونګښانو حتی ډکه شوه شاهي ماڼۍ هم', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms105_verse_30.mp3', '', 1761754199, 1761754199),
(44847, 'Psalms 105:31', 'Psalms', 105, 31, 'د خدای په حکم ټول وطن باندې راغی د میاشو او مچانو لښکر', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms105_verse_31.mp3', '', 1761754199, 1761754199),
(44848, 'Psalms 105:32', 'Psalms', 105, 32, 'د باران په ځای نازله یې ږلۍ کړه د دوی وطن باندې برېښنا او تندر وپړکېده', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms105_verse_32.mp3', '', 1761754199, 1761754199),
(44849, 'Psalms 105:33', 'Psalms', 105, 33, 'ورته تباه یې کړل تاکونه، د انځرو ونې او رانسکورې یې کړې ټولې ونې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms105_verse_33.mp3', '', 1761754199, 1761754199),
(44850, 'Psalms 105:34', 'Psalms', 105, 34, 'د هغه په حکم راغلل ملخان چې وو بې‌شمېره هغوی', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms105_verse_34.mp3', '', 1761754199, 1761754199),
(44851, 'Psalms 105:35', 'Psalms', 105, 35, 'د دې وطن شنه بوټي یې ټول وخوړل او د دوی د ځمکو ټول حاصل یې وخوړ', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms105_verse_35.mp3', '', 1761754199, 1761754199),
(44852, 'Psalms 105:36', 'Psalms', 105, 36, 'د مصریانو په وطن کې د هغوی یې مړه کړل ټول مشران زامن د نارینتوب لومړنۍ مېوه یې کړه ویجاړه ورته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms105_verse_36.mp3', '', 1761754199, 1761754199),
(44853, 'Psalms 105:37', 'Psalms', 105, 37, 'اسراییلیان بیا څښتن وویستل له مصره ځینې سره زر او سپین زر لېږدول هغوی د ځانه سره ټول وو سالم او ځواکمن', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms105_verse_37.mp3', '', 1761754199, 1761754199),
(44854, 'Psalms 105:38', 'Psalms', 105, 38, 'په وتلو د دوی مصریان خوشحاله شول ځکه هغوی ډېر وېرېدلي وو ترې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms105_verse_38.mp3', '', 1761754199, 1761754199),
(44855, 'Psalms 105:39', 'Psalms', 105, 39, 'سیوري دپاره خدای خپره کړه ورېځ په خپلو خلکو اور یې راولېږلو شپه کې د رڼا دپاره', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms105_verse_39.mp3', '', 1761754199, 1761754199),
(44856, 'Psalms 105:40', 'Psalms', 105, 40, 'هغوی ترې سوال وکړ هغه مړزان ورکړل ورته هغوی ته یې ورکړله ډوډۍ د اسمانه څخه چې شي ماړه پرې هغوی', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms105_verse_40.mp3', '', 1761754199, 1761754199),
(44857, 'Psalms 105:41', 'Psalms', 105, 41, 'هغه ګټ وچولو او ترې نه جاري شوې اوبه وبهېدې د سیند په شان دښته کې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms105_verse_41.mp3', '', 1761754199, 1761754199),
(44858, 'Psalms 105:42', 'Psalms', 105, 42, 'ځکه رایاده یې کړه خپله پاکه وعده هغه چې کړې وه څښتن له خدمتګار خپل ابراهیمه سره', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms105_verse_42.mp3', '', 1761754199, 1761754199),
(44859, 'Psalms 105:43', 'Psalms', 105, 43, 'هغه راوویستل خپل خلک له خوشحالۍ سره خپل غوره خلک د سندرو له ویلو سره', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms105_verse_43.mp3', '', 1761754199, 1761754199),
(44860, 'Psalms 105:44', 'Psalms', 105, 44, 'هغوی له وریې کړلې ځمکې د قومونو نورو او دوی راټول کړلو حاصل چې ؤ کرلی نورو', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms105_verse_44.mp3', '', 1761754199, 1761754199),
(44861, 'Psalms 105:45', 'Psalms', 105, 45, 'ترڅو حکمونه د څښتن ومني او قوانین یې عملي کاندي د څښتن ثنا او صفت دې وکړئ!', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms105_verse_45.mp3', '', 1761754199, 1761754199),
(44862, 'Jeremiah 18:1', 'Jeremiah', 18, 1, 'مالِک خُدائ ما يرمياه له پېغام راکړو،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah18_verse_1.mp3', '', 1761754199, 1761754199),
(44863, 'Jeremiah 18:2', 'Jeremiah', 18, 2, '”لاندې د کُلال کور ته لاړ شه، نو هلته به زۀ تا له خپل پېغام درکړم.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah18_verse_2.mp3', '', 1761754199, 1761754199),
(44864, 'Jeremiah 18:3', 'Jeremiah', 18, 3, 'نو زۀ هلته د کُلال کور ته لاړم او ما هغه وليدو چې په خپله څرخه يې کار کولو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah18_verse_3.mp3', '', 1761754199, 1761754199),
(44865, 'Jeremiah 18:4', 'Jeremiah', 18, 4, 'خو چې کوم لوښے به هغۀ د خټې نه جوړولو نو هغه به په لاس کښې هغه شان نۀ راتلو کوم به چې د هغۀ اُميد وو نو بيا به يې هغه خراب کړو او بل څيز به يې ترې نه جوړول شروع کړل کوم به چې هغۀ ته ښۀ ښکارېدو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah18_verse_4.mp3', '', 1761754199, 1761754199),
(44866, 'Jeremiah 18:5', 'Jeremiah', 18, 5, 'بيا مالِک خُدائ ما له دا پېغام راکړو چې،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah18_verse_5.mp3', '', 1761754199, 1761754199),
(44867, 'Jeremiah 18:6', 'Jeremiah', 18, 6, '”اے بنى اِسرائيلو، نو زۀ دا نۀ شم کولے چې تاسو سره هغه کار وکړم کوم به چې کُلال د خټې سره کولو؟ لکه څنګه چې خټه د کُلال په لاس کښې وه، داسې تاسو زما په لاس کښې يئ. دا د مالِک خُدائ فرمان دے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah18_verse_6.mp3', '', 1761754199, 1761754199),
(44868, 'Jeremiah 18:7', 'Jeremiah', 18, 7, 'هرکله کۀ چرې زۀ وغواړم چې يو قوم يا بادشاهت د بېخ نه ختم کړم، يا هغه راوغورزوم او تباه يې کړم،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah18_verse_7.mp3', '', 1761754199, 1761754199),
(44869, 'Jeremiah 18:8', 'Jeremiah', 18, 8, 'او کۀ چرې هغه قوم کوم ته چې ما خبردارے ورکړے وى، د خپلو بدو عملونو نه راوګرځى، نو بيا به زۀ نرمۍ نه کار واخلم او د خپلې ارادې نه به واپس شم او په هغوئ به هغه افت نۀ راولم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah18_verse_8.mp3', '', 1761754199, 1761754199),
(44870, 'Jeremiah 18:9', 'Jeremiah', 18, 9, 'او کۀ بل وخت کښې زۀ چرې دا ووايم چې زۀ به دا قوم يا يو بادشاهت آباد او قائم کړم،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah18_verse_9.mp3', '', 1761754199, 1761754199),
(44871, 'Jeremiah 18:10', 'Jeremiah', 18, 10, 'خو کۀ بيا هغه مُلک زما په وړاندې شرارت کوى او زما تابعدارى ونۀ کړى نو زۀ به د هغه ښۀ کولو اراده پرېږدم د کوم چې ما د هغوئ دپاره اراده کړې وه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah18_verse_10.mp3', '', 1761754199, 1761754199),
(44872, 'Jeremiah 18:11', 'Jeremiah', 18, 11, 'نو اوس زما د طرفه د يهوداه او يروشلم خلقو ته ووايه چې مالِک خُدائ فرمائى چې ګورئ، زۀ په تاسو د افت راوستلو تيارے کوم او ستاسو خلاف منصوبه جوړوم. نو هر يو دې د خپلو بدو طريقو نه راواوړى، او هغه څۀ دې کوى کوم چې ښۀ وى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah18_verse_11.mp3', '', 1761754199, 1761754199),
(44873, 'Jeremiah 18:12', 'Jeremiah', 18, 12, 'خو هغوئ په جواب کښې ووئيل چې، خپله خولۀ دې په مونږ مۀ خرابوه، مونږ چې په کومو طريقو اوسېدل غواړُو هغه شان به اوسيږو، په سرکشۍ سره به د خپل زړۀ بد خواهشونه پوره کوُو.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah18_verse_12.mp3', '', 1761754199, 1761754199),
(44874, 'Jeremiah 18:13', 'Jeremiah', 18, 13, '”نو په دې وجه مالِک خُدائ فرمائى چې، د نورو قومونو د خلقو نه دا تپوس وکړه چې کله هم هغوئ د داسې کار په حقله اورېدلى دى. بنى اِسرائيل دې د پاکې پېغلې په شان وى، خو هغې ډېر بد کار وکړو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah18_verse_13.mp3', '', 1761754199, 1761754199),
(44875, 'Jeremiah 18:14', 'Jeremiah', 18, 14, 'آيا د لبنان د غرونو د څوکو نه کله هم واوره ويلې شوې او ختمه شوې ده څۀ؟ آيا د هغوئ د غريزه او لرې چينو يخې اوبۀ بهېدل کله ختم شوى دى څۀ؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah18_verse_14.mp3', '', 1761754199, 1761754199),
(44876, 'Jeremiah 18:15', 'Jeremiah', 18, 15, 'بلکې زما خلقو زۀ هېر کړے يم، او هغوئ بې‌کاره بُتانو ته خوشبويۍ وسوزولې، بُتان کوم چې د هغوئ د تيندک باعث شُو او دوئ يې د پخوانو ښو لويو لارو نه جدا کړل او په کچه لارو باندې روان شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah18_verse_15.mp3', '', 1761754199, 1761754199),
(44877, 'Jeremiah 18:16', 'Jeremiah', 18, 16, 'نو په دې وجه به د هغوئ مُلک په بيابان بدل کړے شى او نورو ته به د خندا ذريعه وګرځى. څوک هم چې په دې لاره تېريږى نو هغوئ به حق حيران شى او د يهوداه په حالت به يې د يرې نه وېښتۀ نيغ ودريږى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah18_verse_16.mp3', '', 1761754199, 1761754199),
(44878, 'Jeremiah 18:17', 'Jeremiah', 18, 17, 'نو زۀ به لکه د نمرخاتۀ د باد په شان هغوئ د دشمنانو په وړاندې خوارۀ وارۀ کړم. او د هغوئ د مصيبت په ورځ به زۀ خپل مخ د هغوئ نه واړوم او د هغوئ فريادونه به نۀ اورم.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah18_verse_17.mp3', '', 1761754199, 1761754199),
(44879, 'Jeremiah 18:18', 'Jeremiah', 18, 18, 'نو بيا خلقو ووئيل، ”راځئ چې د يرمياه خلاف منصوبه جوړه کړُو. ځکه چې مونږ سره ډېر اِمامان، هوښياران او نبيان شته دے. مونږ ته د هغۀ د شريعت د تعليم، نصيحت او پېشګويۍ ورکولو ضرورت نشته دے. راځئ چې په خولۀ د هغۀ په حقله افواګانې خورې کړُو او په هغۀ اِلزام ولګوو او دوئ چې څۀ هم وائى نور ورته غوږ ونۀ نيسو.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah18_verse_18.mp3', '', 1761754199, 1761754199),
(44880, 'Jeremiah 18:19', 'Jeremiah', 18, 19, 'نو بيا ما ووئيل چې، ”اے مالِکه خُدايه، ما ته غوږ ونيسه او زما دشمنان چې زما خلاف څۀ وائى په هغې غور وکړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah18_verse_19.mp3', '', 1761754199, 1761754199),
(44881, 'Jeremiah 18:20', 'Jeremiah', 18, 20, 'ولې هغوئ د ښو بدله په بدو سره ورکوى څۀ؟ اوس خو هغوئ زما د وژلو دپاره کنده کنستلې ده. هغه وخت راياد کړه چې زۀ به ستا په حضور کښې ودرېدم او د هغوئ سفارش به مې تاسو ته کولو چې په هغوئ باندې خپل قهر او غضب مۀ نازلوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah18_verse_20.mp3', '', 1761754199, 1761754199),
(44882, 'Jeremiah 18:21', 'Jeremiah', 18, 21, 'خو اے مالِکه خُدايه، اوس پرېږده چې د هغوئ بچى د لوږې نه مړۀ شى، پرېږده چې هغوئ په تُوره قتل کړے شى. د هغوئ ښځې دې بورې او کونډې شى، پرېږده چې د هغوئ بوډاګان سړى په وبا مړۀ شى، پرېږده چې د هغوئ ځوانان په جنګ مړۀ شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah18_verse_21.mp3', '', 1761754199, 1761754199),
(44883, 'Jeremiah 18:22', 'Jeremiah', 18, 22, 'پرېږده چې ناګهانه په هغوئ جنګى سپاهيان ورننوځى، او د هغوئ د کورونو نه دې چغې او سورې واورېدلے شى. ځکه چې هغوئ زما دپاره کنده کنستلې ده او پټ دام يې راته خور کړے دے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah18_verse_22.mp3', '', 1761754199, 1761754199),
(44884, 'Jeremiah 18:23', 'Jeremiah', 18, 23, 'خو اے مالِکه خُدايه، تۀ د هغوئ په ټولو منصوبو باندې پوهه يې چې زما د وژلو دپاره يې تيارې کړې دى. تۀ د هغوئ جرم مۀ معاف کوه او مۀ د هغوئ ګناه د خپلو سترګو نه اخوا کوه. پرېږده چې هغوئ ستا په وړاندې راوغورزيږى، او په خپل قهر او غضب کښې هغوئ له سزا ورکړه.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah18_verse_23.mp3', '', 1761754199, 1761754199),
(44885, 'Isaiah 53:1', 'Isaiah', 53, 1, 'چا باور کړی دی زمونږ پیغام باندې؟ ښکاره شوی چاته د څښتن قوي لاس؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah53_verse_1.mp3', '', 1761754199, 1761754199),
(44886, 'Isaiah 53:2', 'Isaiah', 53, 2, 'داسې لوی شو د څښتن په مخکې خدمتګار د هغه لکه تنکي نیالګي په شان چې ریښې نیسي په وچه ځمکه کې نه درلودله هغه داسې ښکلا یا ښایست چې زمونږ پام یې اړولی وای خپل ځان ته هغه کې نه ؤ داسې جالب شی چې لېوال شوي وای مونږ ورته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah53_verse_2.mp3', '', 1761754199, 1761754199),
(44887, 'Isaiah 53:3', 'Isaiah', 53, 3, 'خلکو کتل هغه ته په سپکه سترګه او هغه یې رد کړ هغه وزغمل دردونه او کړاوونه حتی هر چا مخ اړوه له هغه خلکو کتل هغه ته په سپکه سترګه نه ورکاوه مونږه هغه ته ارزښت', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah53_verse_3.mp3', '', 1761754199, 1761754199),
(44888, 'Isaiah 53:4', 'Isaiah', 53, 4, 'بې له شکه هغه وزغمل زمونږ کړاوونه او خپلو اوږو باندې یې یووړل زمونږ دردونه هغه دردونه چې هغه وزغمل باید زغملي وای مونږ خو مونږ فکر کاوه چې یوه سزا ده دا دردونه چې راغلي په هغه باندې د خدای له خوا نه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah53_verse_4.mp3', '', 1761754199, 1761754199),
(44889, 'Isaiah 53:5', 'Isaiah', 53, 5, 'خو هغه ټپي ټپي شو زمونږ د ګناهونو په خاطر هغه ووهل شو زمونږ د بدو کارونو په خاطر د هغې سزا په خاطر چې هغه وزغمله را په برخه شوله مونږ ته ارامي د هغه د ټپونو نه مونږ وموندله روغتیا', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah53_verse_5.mp3', '', 1761754199, 1761754199),
(44890, 'Isaiah 53:6', 'Isaiah', 53, 6, 'مونږ ټول وو لکه ورکو پسونو په شان هر یو روان ؤ سرګردان په خپله لاره خو څښتن کېښودله زمونږ ټوله ګناه د هغه په اوږو باندې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah53_verse_6.mp3', '', 1761754199, 1761754199),
(44891, 'Isaiah 53:7', 'Isaiah', 53, 7, 'په هغه ظلم وشو خو ویې زغملو په عاجزۍ سره هغه هېڅ ونه ویل لکه څوک چې وړي وری حلالولو ته لکه څنګه چې وي غلی پسه د سکولوونکو مخکې هغه هېڅ ونه ویل', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah53_verse_7.mp3', '', 1761754199, 1761754199),
(44892, 'Isaiah 53:8', 'Isaiah', 53, 8, 'هغه ونیول شو او په مرګ محکوم شو او یووړل شو اعدام ته هغه یې وواژه زما د قوم د جرمونو په خاطر او هېچا یې ونه کړه پروا', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah53_verse_8.mp3', '', 1761754199, 1761754199),
(44893, 'Isaiah 53:9', 'Isaiah', 53, 9, 'هغه یې ښخ کړ د مجرمانو په شان او د یو شتمن سړي په قبر کې یې کېښود هغه که څه هم هغه هېڅکله کړی نه ؤ ظلم او تېری او نه یې څوک ؤ غولولی', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah53_verse_9.mp3', '', 1761754199, 1761754199),
(44894, 'Isaiah 53:10', 'Isaiah', 53, 10, 'خو دا رضا وه د څښتن چې هغه ووهي او ویې کړوي ترڅو قرباني شي د ګناه په خاطر د هغه ژوند نو هغه به وویني خپل اولادونه او وبه لري زیات عمر شي پوره به د څښتن رضا په وسیله د هغه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah53_verse_10.mp3', '', 1761754199, 1761754199),
(44895, 'Isaiah 53:11', 'Isaiah', 53, 11, 'هغه به وګوري رڼا له یو دردناکه ژوندانه نه وروسته او شي به ډاډه چې کړېدنه یې بېځایه نه وه کړي تجربه به کړېدنه زما عادل خدمتګار دا به ممکن کړي چې عادل وګڼل شي ډېر خلک ځکه هغه به یوسي ګناهونه د هغوی خپلو اوږو باندې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah53_verse_11.mp3', '', 1761754199, 1761754199),
(44896, 'Isaiah 53:12', 'Isaiah', 53, 12, 'نو زه به ورکړمه هغه ته د عزت مقام مقام به ورکړم د لویانو او زورورو ورته ځکه هغه کړلو قربان خپل ځان او وشمېرل شو په مجرمانو کې په ځان یې واخیسته د ډېرو خلکو ګناه او د مجرمانو دپاره یې وکړه دعا', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah53_verse_12.mp3', '', 1761754199, 1761754199),
(44897, 'Job 36:1', 'Job', 36, 1, 'اليهُو خپله خبره جارى وساتله او وې وئيل،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job36_verse_1.mp3', '', 1761754199, 1761754199),
(44898, 'Job 36:2', 'Job', 36, 2, '”ما ته لږ صبر وکړئ، نو زۀ به تاسو ته حقيقت وښايم، ځکه چې زۀ د خُدائ پاک په صفايئ کښې څۀ وئيل غواړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job36_verse_2.mp3', '', 1761754199, 1761754199),
(44899, 'Job 36:3', 'Job', 36, 3, 'زۀ به د خپل ډېر عِلم نه کار واخلم، چې دا ثابت کړم چې زما خالِق د اِنصاف مالِک دے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job36_verse_3.mp3', '', 1761754199, 1761754199),
(44900, 'Job 36:4', 'Job', 36, 4, 'په حقيقت کښې زما خبرې غلطې نۀ دى، څوک چې ستا په وړاندې ولاړ دے هغه د اُستاذانو اُستاذ دے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job36_verse_4.mp3', '', 1761754199, 1761754199),
(44901, 'Job 36:5', 'Job', 36, 5, 'خُدائ پاک بې‌شکه لوئ دے او د هيچا نه نفرت نۀ کوى، داسې يو عِلم هم نشته چې هغه يې نۀ لرى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job36_verse_5.mp3', '', 1761754199, 1761754199),
(44902, 'Job 36:6', 'Job', 36, 6, 'هغه بدعمله خلق ژوندى نۀ پرېږدى، خو مظلومانو له خپل حق ورکوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job36_verse_6.mp3', '', 1761754199, 1761754199),
(44903, 'Job 36:7', 'Job', 36, 7, 'هغه د صادقانو حفاظت کوى، او د بادشاهانو سره يې په تخت کښېنوى او د تل دپاره عزت ورکوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job36_verse_7.mp3', '', 1761754199, 1761754199),
(44904, 'Job 36:8', 'Job', 36, 8, 'خو کۀ خلق په زنځيرونو کښې تړلے شوى وى او د ظلم په تارونو کښې ګېر شوى وى،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job36_verse_8.mp3', '', 1761754199, 1761754199),
(44905, 'Job 36:9', 'Job', 36, 9, 'نو هغه ورته د هغوئ خپل عمل ښائى، او هغه غلطيانې ورته ښائى، چې کومې هغوئ په فخر سره کولې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job36_verse_9.mp3', '', 1761754199, 1761754199),
(44906, 'Job 36:10', 'Job', 36, 10, 'هغه اصُولو ته يې پام راګرځوى، او حُکم ورکوى چې د بدو نه توبه وباسى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job36_verse_10.mp3', '', 1761754199, 1761754199),
(44907, 'Job 36:11', 'Job', 36, 11, 'کۀ هغوئ ورته توجو ورکړى او د هغۀ خِدمت وکړى، نو هغوئ به په مالدارۍ کښې خپلې ورځې پوره کړى، او په خوشحالۍ کښې به خپل کالونه پوره کړى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job36_verse_11.mp3', '', 1761754199, 1761754199),
(44908, 'Job 36:12', 'Job', 36, 12, 'خو کۀ هغوئ دې ته توجو ورنۀ کړى، نو هغوئ به په جهالت کښې هلاک شى او د خاورو د لاندې به شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job36_verse_12.mp3', '', 1761754199, 1761754199),
(44909, 'Job 36:13', 'Job', 36, 13, 'کوم خلق چې د خُدائ پاک نه منکر وى او هر وخت په غصه کښې وى، چې کله هغوئ ته سزا هم ملاويږى نو هغوئ د مدد دپاره دُعا نۀ کوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job36_verse_13.mp3', '', 1761754199, 1761754199),
(44910, 'Job 36:14', 'Job', 36, 14, 'هغوئ په ځوانۍ کښې مړۀ شى، او د هغوئ ژوند په زناکارۍ کښې ختم شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job36_verse_14.mp3', '', 1761754199, 1761754199);